before:
- name: Upload Test Results
  if: always()
  uses: actions/upload-artifact@v6
  with:
    name:
      playwright-report-normal-${{ matrix.os }}-${{ matrix.browser }}-${{
      github.run_id }}
    path: test-results/
    retention-days: 7
    if-no-files-found: ignore

after:
# Public artifacts contain workflow metadata only. Never upload raw evidence.
- name: Prepare safe artifact summary
  id: safe_artifact
  if: always()
  run: node scripts/artifact-safe-summary.mjs
  env:
    SAFE_TEST_SUITE: normal
    SAFE_TEST_OS: ${{ matrix.os }}
    SAFE_TEST_BROWSER: ${{ matrix.browser }}
    SAFE_TEST_EXIT_CODE: ${{ steps.run_tests.outputs.EXIT_CODE }}

- name: Upload safe workflow summary
  if: ${{ always() && steps.safe_artifact.outcome == 'success' && steps.safe_artifact.outputs.verified == 'true' && steps.safe_artifact.outputs.summary_path != '' }}
  uses: actions/upload-artifact@v6
  with:
    name:
      workflow-summary-normal-${{ matrix.os }}-${{ matrix.browser }}-${{
      github.run_id }}
    path: ${{ steps.safe_artifact.outputs.summary_path }}
    retention-days: 7
    if-no-files-found: error
    include-hidden-files: false

